function tradeTier(p){const o=overall(p),age=Number(p.age||27),pot=Number(p.dev?.ceiling||o);if(o>=94||(o>=91&&age<=28))return 6;if(o>=90||(o>=87&&age<=24&&pot>=90))return 5;if(o>=86||(o>=83&&age<=23&&pot>=88))return 4;if(o>=82)return 3;if(o>=77||(age<=23&&pot>=84))return 2;if(o>=73)return 1;return 0}
